28	  const verifyDir = `_verify/${branch.replace(/[^\w.-]+/g, "-")}`;
29	  const verifyPath = (name) => `${verifyDir}/${name}`;
30	  const writeNote = (name, body) =>
31	    client.evaluate(`
32	      return (async () => {
33	        const p = ${json(verifyPath(name))};
34	        for (const dir of [${json("_verify")}, ${json(verifyDir)}])
35	          if (!app.vault.getAbstractFileByPath(dir)) await app.vault.createFolder(dir);
36	        const f = app.vault.getAbstractFileByPath(p);
37	        if (f) await app.vault.modify(f, ${json(body)});
38	        else await app.vault.create(p, ${json(body)});
39	        return p;
40	      })();
41	    `);
42	  return { client, vault, branch, json, verifyDir, verifyPath, writeNote };
43	};
44	
45	export const runVerification = async ({ client, vault, branch, scenarios, artifactsDir, meta = {} }) => {
46	  mkdirSync(artifactsDir, { recursive: true });
47	  const ctx = makeContext({ client, vault, branch });
48	  const baselineLayout = await client.evaluate(`return app.workspace.getLayout();`);
49	  const shaBefore = bundleHash(vault.pluginDir);
50	  const results = [];
51	
52	  const resetToBaseline = async () => {
53	    await client.clearModals();
54	    await client.evaluate(`return app.workspace.changeLayout(${json(baselineLayout)}).then(() => true);`);
55	  };
56	
57	  try {
58	    for (const [i, scenario] of scenarios.entries()) {
59	      const started = Date.now();
60	      const row = { scenario: scenario.name, input: scenario.input ?? "", expected: scenario.expected ?? "" };
61	      let state;
62	      try {
63	        await resetToBaseline();
64	        state = scenario.setup ? await scenario.setup(ctx) : undefined;
65	        const actual = await scenario.run(ctx, state);
66	        const shot = path.join(artifactsDir, `${i + 1}-${slugify(scenario.name)}.png`);
67	        writeFileSync(shot, await client.screenshot());
68	        row.screenshot = shot;
69	        const verdict = await scenario.expect(actual, state);
70	        row.pass = typeof verdict === "object" ? !!verdict.pass : !!verdict;
71	        row.actual = toText(typeof verdict === "object" && "actual" in verdict ? verdict.actual : actual);
72	      } catch (error) {
73	        row.pass = false;
74	        row.actual = `ERROR: ${error.message.split("\n")[0]}`;
75	      } finally {
76	        if (scenario.teardown)
77	          await Promise.resolve(scenario.teardown(ctx, state)).catch((e) => console.error(`teardown failed: ${e.message}`));
78	      }
79	      row.ms = Date.now() - started;
80	      results.push(row);
81	      console.log(`${row.pass ? "PASS" : "FAIL"}  ${row.scenario} (${row.ms}ms) ${row.pass ? "" : row.actual}`);
82	    }
83	  } finally {
84	    await resetToBaseline().catch(() => {});
85	  }
86	
87	  const bundleChanged = bundleHash(vault.pluginDir) !== shaBefore;
88	  if (bundleChanged) console.error("INVALID RUN: main.js changed mid-run (another watcher?)");
89	  const lastRun = {
90	    ...meta,
91	    branch,
92	    vault: vault.root,
93	    slot: vault.slot,
94	    verifyDir: ctx.verifyDir,
95	    bundleChangedDuringRun: bundleChanged,
96	    pass: !bundleChanged && results.every((r) => r.pass),
97	    results,
98	  };
99	  const lastRunPath = path.join(artifactsDir, "last-run.json");
100	  writeFileSync(lastRunPath, JSON.stringify(lastRun, null, 2));
101	  return { lastRun, lastRunPath };
102	};
103	
104	const cell = (s) => String(s ?? "").replace(/\|/g, "\\|").replace(/\n/g, " ");
105	
106	export const matrixMarkdown = (results) =>
107	  [
108	    "| Scenario | Input | Expected | Actual | Pass |",
109	    "| --- | --- | --- | --- | --- |",
110	    ...results.map(
111	      (r) => `| ${cell(r.scenario)} | ${cell(r.input)} | ${cell(r.expected)} | ${cell(r.actual)} | ${r.pass ? "yes" : "no"} |`,
112	    ),
113	  ].join("\n");

